from pathlib import Path
import json,re,hashlib
p=Path(__file__).resolve().parent
def read(name):return json.loads((p/name).read_text())
tests=(p/'tests.log').read_text();count=int(re.search(r'^# tests (\d+)$',tests,re.M)[1]);assert re.search(r'^# fail 0$',tests,re.M)
jsc=read('conversion-jsc-results.json');cold=read('native-first-load-results.json');filled=read('native-filled-first-load-results.json');churn=read('native-churn-results.json');pressure=read('native-pressure-results.json');static=read('policy-native-churn-results.json')
def hashes(root):return {str(f.relative_to(root/'runtime')):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted((root/'runtime').rglob('*')) if f.is_file()}
baseline=Path('/var/folders/nd/7mjnltf526q8zsj7g6h92frh0000gn/T/verselyrics-310-yvd48xy3/310');runtime=hashes(p);prior=hashes(baseline);assert runtime==read('bench-runtime-sha256.json') and len(runtime)==15
for run in jsc['runs']:
 hook='Loon/script/SpotifyLyrics.Entry.js' if run['scenario'].startswith(('entry-','wire-')) else 'Loon/script/SpotifyLyrics.js'
 assert run['runtimeSHA256']==(prior if run['version']=='baseline' else runtime)[hook]
assert (p/'final-benchmarks.log').read_text().count('passed; final runtime hashes unchanged')==6
def percent(a,b):return 100*(a/b-1)
def ranges(rows,key):
 values=[percent(r['candidate'][key],r['baseline'][key]) for r in rows];return [round(min(values),3),round(max(values),3)]
comparisons={}
for mode in ['cold','sequence']:
 for changed in [False,True]:
  selected=[r for r in jsc['comparisons'] if r['mode']==mode and r['intentionalBehaviorChange']==changed]
  comparisons[mode+('-conversion-fix' if changed else '-unchanged')]={'cases':len(selected),'peakPercent':ranges(selected,'sampledPeakFootprint'),'elapsedPercent':ranges(selected,'milliseconds')}
summary={'version':'3.1.1','adapter':14,'baselineVersion':'3.1.0','baselineRuntimeCommit':'4a74064675bf7224fdd45859dc0b513ffa074c6c','tests':{'passed':count,'failed':0},'newRegressionChecks':count-1253,'runtimeFiles':len(runtime),'jsc':{'processes':len(jsc['runs']),'comparisons':len(jsc['comparisons']),'groups':comparisons},'nativeCold':{'processes':len(cold['runs']),'peakPercent':ranges(cold['comparisons'],'sampledMaxHeapBytes'),'elapsedPercent':ranges(cold['comparisons'],'medianMs')},'nativeFilled':{'processes':len(filled['runs']),'peakPercent':ranges(filled['comparisons'],'sampledMaxHeapBytes'),'elapsedPercent':ranges(filled['comparisons'],'medianMs')},'existingChurn':{'processes':len(churn['results']),'songsPerProcess':240,'httpPerProcess':720,'maxActiveHTTP':max(r['maxActiveHTTP'] for r in churn['results'])},'staticChurn':{'processes':len(static['results']),'songsPerProcess':120,'responsesPerProcess':240,'httpPerProcess':240,'maxActiveHTTP':max(r['maxActiveHTTP'] for r in static['results']),'unfinishedHTTP':max(r['activeHTTP'] for r in static['results']),'maxStandardCacheCharacters':max(r['maxCacheCharacters'] for r in static['results'] if r['mode']=='standard'),'maxCompactCacheCharacters':max(r['maxCacheCharacters'] for r in static['results'] if r['mode']=='compact')},'pressure':pressure['comparisons'],'candidateRuntimeSHA256':runtime,'baselineRuntimeSHA256':prior,'deviceAcceptance':{'iPhoneLoon':False,'vpnStability':False,'exactUserPhoneResponse':False},'scope':'Reproduced 3.1.0 code paths, 1357 automated checks, two public synthetic translation API observations and scoped macOS JSC/Node native mocks. Not native client import, phone traffic, catalog completeness or VPN acceptance.'}
(p/'validation-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
def fmt(x):return f'{x[0]:+.3f}% to {x[1]:+.3f}%'
lines=['# VerseLyrics 3.1.1 measurements','',f'**{count} automated tests pass, zero fail**. Native Egern YAML checks pass. This adds {count-1253} regression checks to 3.1.0, including all five compiled adapters in JSON/protobuf and both Chinese targets. Baseline runtime/source is the unchanged published 3.1.0 at commit 4a74064675bf7224fdd45859dc0b513ffa074c6c.','', '## Reproduced bug and result','', 'Independent 3.1.0 fixtures emitted conversion for a Chinese/Latin row, a wrongly labelled Chinese row and a cached conversion. Two real unauthenticated public translation requests with synthetic text confirmed that a Chinese/Latin row can be returned with detected language en, so detection metadata alone is insufficient. Exact samples and limits are in regression-reproduction.json. No user phone traffic was captured.','', 'The candidate preserves Chinese rows with Latin names/ad-libs or Bopomofo before translation, checks every cache/provider/service result at output, and remembers an identity result when the service explicitly detects Chinese. Existing conversion cache entries are filtered without clearing the entire store. Output equivalence uses the existing Unicode data and a few common orthographic equivalents; it compares code points without constructing two converted lyric strings or converting visible originals.','', '## First load and repeated contexts','', '| Experiment | Median sampled peak change | Median elapsed change |','| --- | --- | --- |']
for key,label in [('cold-unchanged','JSC cold: 18 unchanged cases'),('sequence-unchanged','JSC sequence: 2 unchanged cases × 32 contexts'),('cold-conversion-fix','JSC cold: 6 corrected conversion cases'),('sequence-conversion-fix','JSC sequence: 6 corrected cases × 32 contexts')]:
 r=comparisons[key];lines.append(f"| {label} | {fmt(r['peakPercent'])} | {fmt(r['elapsedPercent'])} |")
for key,label in [('nativeCold','Node cold: 10 cases / 240 processes'),('nativeFilled','Node filled cache: 10 cases / 240 processes')]:
 r=summary[key];lines.append(f"| {label} | {fmt(r['peakPercent'])} | {fmt(r['elapsedPercent'])} |")
lines+=['','Existing scenarios require identical byte fingerprints and request counts, including static-to-timed upgrade behavior retained from 3.1.0. The corrected mixed Chinese/Latin fixture drops one unnecessary translation HTTP request to zero. Stale conversion-cache fixtures use zero HTTP in both versions; only the candidate omits the duplicate converted line. Service-detected Chinese fixtures use one cold request in both versions, while unit/native reopen checks confirm zero further HTTP with the identity cache.','', 'Results contain both increases and decreases. In particular, some repeated-context conversion cases increase sampled JSC footprint even though cold cases decrease; the report makes no universal memory or speed claim. The new check adds bounded CPU work and reuses the existing translation cache. Raw per-case trials retain runtime hashes, request counts and exact original-passthrough assertions. Desktop allocator/JIT samples are not an iPhone Loon peak or VPN stability measurement.','', '## Switching and pressure','', '- Existing missing-lyrics churn: five candidate clients × JSON/protobuf, 240 different song IDs and 720 HTTP calls per process, same bytes as 3.1.0, maximum active HTTP one.','- Retained static-to-timed churn: five clients × two representations × two cache modes, 20 separate processes. Each handles 120 song IDs and 240 lyric responses including immediate cached reopen, 240 source calls total, zero calls on reopen and zero unfinished HTTP. Maximum active HTTP stays one.','- Standard cache maximum was '+str(summary['staticChurn']['maxStandardCacheCharacters'])+' serialized characters; compact maximum was '+str(summary['staticChurn']['maxCompactCacheCharacters'])+'. Limits remain 64,000/32,000 characters and 128/64 entries.','- Pressure fixtures retain the established maximum two live invocations and one HTTP request under 60 arrivals at two-millisecond spacing and delayed callbacks. No admission timers; busy misses stay retryable.','- Node old-space is capped at 32 MiB for the harness, with explicit GC in churn cases. This is not a Loon memory limit. Egern completion is an awaited return rather than a native $done call.','', '## Reproduce','', 'Use the pinned 3.1.0 runtime/source as a separate BASELINE directory. Build dependencies remain pinned by pnpm-lock.yaml; the only runtime data table is the existing licensed Unicode data.','', '```sh','pnpm install --frozen-lockfile','node build.mjs','python3 package.py','node --test --test-reporter=tap *.test.mjs core/test/*.test.mjs','ruby validate-egern.rb','node jsc-fixtures.mjs','node jsc-cache-fixtures.mjs','node jsc-release-fixtures.mjs','node jsc-300-fixtures.mjs','node jsc-policy-fixtures.mjs','node conversion-fixtures.mjs','clang -isysroot /Library/Developer/CommandLineTools/SDKs/MacOSX.sdk -O2 -framework JavaScriptCore jsc-memory-runner.c -o jsc-memory-runner','python3 run-final-311.py "$(command -v node)" "$BASELINE"','```','', 'The runner executes all measurements sequentially and aborts if any runtime hash changes. JSC has 24 cold cases and eight 32-context cases, six alternating trials per version, 384 fresh processes. Node first-load reports have 240 processes each. Data files: conversion-jsc-results.json, native-first-load-results.json, native-filled-first-load-results.json, native-churn-results.json, native-pressure-results.json and policy-native-churn-results.json. Final hashes are in bench-runtime-sha256.json and validation-summary.json.','']
(p/'MEASUREMENTS.md').write_text('\n'.join(lines));print(json.dumps({k:summary[k] for k in ['version','tests','newRegressionChecks','jsc','nativeCold','nativeFilled','staticChurn']}))
